145	\begin{definition}[Measurements and submeasurements]\label{def:submeasurement}
146		\lean{MIPStarRE.LDT.SubMeas, MIPStarRE.LDT.Measurement, MIPStarRE.LDT.ProjSubMeas}
147		\leanok
148		Let $\mathcal H$ be a Hilbert space and let $\mathcal A$ be a set of outcomes. A submeasurement on $\mathcal A$ is a family $A=\{A_a\}_{a \in \mathcal A}$ of Hermitian positive semidefinite operators on $\mathcal H$ such that $\sum_a A_a \le I$. It is a measurement when $\sum_a A_a = I$, and it is projective when each $A_a$ is an idempotent projection. (In the Lean formalization, outcome sets are assumed finite throughout.)
149	\end{definition}
150	
151	\begin{definition}[Low-degree polynomial measurements]\label{def:polymeasurements}
152		\lean{MIPStarRE.LDT.SubMeas, MIPStarRE.LDT.Measurement, MIPStarRE.LDT.Polynomial}
153		\leanok
154		\uses{def:polyfunc, def:submeasurement}
155		We write $\polysub{m}{q}{d}$ for the submeasurements indexed by $\polyfunc{m}{q}{d}$, and $\polymeas{m}{q}{d}$ for the corresponding measurements.
156	\end{definition}
157	
158	\begin{definition}[Post-processing]\label{def:post-processing}
159		\lean{MIPStarRE.LDT.postprocess}
160		\leanok
161		\uses{def:submeasurement}
162		Let $A=\{A_a\}_{a \in \mathcal A}$ be a family of operators and let $f\colon \mathcal A \to \mathcal B$. The post-processed family $A_{[f(a)=b]}$ is defined by
163		\[
164			A_{[f(a)=b]} = \sum_{a\, :\, f(a)=b} A_a.
165		\]
166	\end{definition}
167	
168	\begin{proposition}[Post-processing preserves measurements]\label{prop:post-processing-preserves}
169		\lean{MIPStarRE.LDT.Preliminaries.postprocessPreservesMeasurements, MIPStarRE.Quantum.Submeasurement.postprocess_sum_eq, MIPStarRE.Quantum.Measurement.postprocess}
170		\leanok
171		\uses{def:post-processing, def:submeasurement}
172		Let $A=\{A_a\}_{a \in \mathcal A}$ be a family of operators and let
173		$f\colon \mathcal A \to \mathcal B$. Then
174		\[
175			\sum_a A_a = \sum_b A_{[f(a)=b]}.
176		\]
177		Consequently, if $\{A_a\}$ is a submeasurement, respectively a measurement, then
178		$\{A_{[f(a)=b]}\}$ is again a submeasurement, respectively a measurement.
179	\end{proposition}
180	\begin{proof}
181		\leanok
182		Each $a \in \mathcal A$ contributes exactly once to the right-hand side, namely in
183		the summand indexed by $b=f(a)$.
184	\end{proof}
